{
  "explanation": "Set the two cost formulas equal: 20 + 0.10x = 35 + 0.05x. Subtracting gives 0.05x = 15, so x = 300 minutes — at that point both plans cost exactly $50. Below 300 minutes Plan A is cheaper (lower flat fee); above 300 minutes Plan B wins (lower per-minute rate). Drag the Minutes slider to compare the plans at any usage level and watch the dots meet at the break-even point.",
  "manimCode": "// Cost functions
const planA = m => 20 + 0.10 * m;
const planB = m => 35 + 0.05 * m;

// Axes: x = minutes (0-600), y = cost in dollars (0-80)
const ax = new Axes({
  xRange: [0, 600, 100],
  yRange: [0, 80, 10],
  xLength: 9.5,
  yLength: 6,
  tips: true
});
ax.moveTo([-1.2, -0.3, 0]);

const title = new Text({ text: 'Phone Plan Break-Even', color: WHITE, fontSize: 30 });
title.moveTo([-1.2, 3.55, 0]);
scene.add(title);

await scene.play(new Create(ax));

// Plot both plans on the SAME axes so they align
const lineA = ax.plot(planA, { color: BLUE, xRange: [0, 600] });
const lineB = ax.plot(planB, { color: ORANGE, xRange: [0, 600] });
await scene.play(new AnimationGroup([new Create(lineA), new Create(lineB)]));

// Legend
const legendA = new MathTex({ latex: 'A(x) = 20 + 0.10x' });
await legendA.waitForRender();
legendA.setColor(BLUE);
legendA.moveTo([-3.2, 2.6, 0]);
const legendB = new MathTex({ latex: 'B(x) = 35 + 0.05x' });
await legendB.waitForRender();
legendB.setColor(ORANGE);
legendB.moveTo([-3.2, 2.0, 0]);
await scene.play(new AnimationGroup([new FadeIn(legendA), new FadeIn(legendB)]));

// Break-even point (300, 50) with guide lines
const breakDot = new Dot({ point: ax.c2p(300, 50), color: YELLOW });
const guideV = new Line({ start: ax.c2p(300, 0), end: ax.c2p(300, 50), color: GRAY });
guideV.setStrokeWidth(1.5).setOpacity(0.5);
const guideH = new Line({ start: ax.c2p(0, 50), end: ax.c2p(300, 50), color: GRAY });
guideH.setStrokeWidth(1.5).setOpacity(0.5);
const breakLabel = new Text({ text: 'Break-even: 300 min, $50', color: GOLD, fontSize: 24 });
breakLabel.moveTo([-1.2, 1.15, 0]);
await scene.play(new AnimationGroup([new Create(guideV), new Create(guideH), new FadeIn(breakDot), new FadeIn(breakLabel)]));

// Algebraic solution on the right panel
const solEq = new MathTex({ latex: '20 + 0.10x = 35 + 0.05x' });
await solEq.waitForRender();
solEq.scale(0.8);
solEq.moveTo([5.1, -1.2, 0]);
const solEq2 = new MathTex({ latex: '0.05x = 15' });
await solEq2.waitForRender();
solEq2.scale(0.8);
solEq2.moveTo([5.1, -1.95, 0]);
const solEq3 = new MathTex({ latex: 'x = 300' });
await solEq3.waitForRender();
solEq3.setColor(GOLD);
solEq3.scale(0.9);
solEq3.moveTo([5.1, -2.7, 0]);
await scene.play(new AnimationGroup([new FadeIn(solEq), new FadeIn(solEq2), new FadeIn(solEq3)]));

// Axis name labels
const xLab = new Text({ text: 'minutes', color: GRAY, fontSize: 20 });
xLab.moveTo([4.1, -3.3, 0]);
const yLab = new Text({ text: 'cost ($)', color: GRAY, fontSize: 20 });
yLab.moveTo([-5.3, 3.05, 0]);
scene.add(xLab, yLab);

// Interactive minute tracker
let mins = 150;

const dotA = new Dot({ point: ax.c2p(mins, planA(mins)), color: BLUE });
const dotB = new Dot({ point: ax.c2p(mins, planB(mins)), color: ORANGE });
const vLine = new Polygon({ vertices: [ax.c2p(mins, 0), ax.c2p(mins, Math.max(planA(mins), planB(mins)))], color: GOLD });
vLine.setStrokeWidth(2).setFillOpacity(0).setOpacity(0.8);

dotA.addUpdater(() => dotA.moveTo(ax.c2p(mins, planA(mins))));
dotB.addUpdater(() => dotB.moveTo(ax.c2p(mins, planB(mins))));
vLine.addUpdater(() => vLine.setVertices([ax.c2p(mins, 0), ax.c2p(mins, Math.max(planA(mins), planB(mins)))]));

scene.add(vLine, dotA, dotB);

// Dynamic readout (Text is immutable: remove + recreate on change)
let minText = null, costAText = null, costBText = null, verdictText = null;

function drawReadout() {
  minText = new Text({ text: 'Minutes: ' + mins, color: WHITE, fontSize: 26 });
  minText.moveTo([5.1, 1.9, 0]);
  costAText = new Text({ text: 'Plan A: $' + planA(mins).toFixed(2), color: BLUE, fontSize: 26 });
  costAText.moveTo([5.1, 1.25, 0]);
  costBText = new Text({ text: 'Plan B: $' + planB(mins).toFixed(2), color: ORANGE, fontSize: 26 });
  costBText.moveTo([5.1, 0.6, 0]);
  const diff = planA(mins) - planB(mins);
  let vStr, vColor;
  if (Math.abs(diff) < 1e-9) { vStr = 'Same cost!'; vColor = GOLD; }
  else if (diff < 0) { vStr = 'Plan A is cheaper'; vColor = BLUE; }
  else { vStr = 'Plan B is cheaper'; vColor = ORANGE; }
  verdictText = new Text({ text: vStr, color: vColor, fontSize: 26 });
  verdictText.moveTo([5.1, -0.2, 0]);
  scene.add(minText, costAText, costBText, verdictText);
}
drawReadout();

function refreshReadout() {
  scene.remove(minText);
  scene.remove(costAText);
  scene.remove(costBText);
  scene.remove(verdictText);
  drawReadout();
}

// Slider to explore usage levels
const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({
  label: 'Minutes',
  min: 0,
  max: 600,
  value: 150,
  step: 10,
  onChange: (val) => { mins = val; refreshReadout(); }
});

await scene.wait(999999);"
}

